function burst(x,y,z,material,size=1){let ring=mesh(fx,torusGeo,material,x,y,z,.5*size,.5*size,.5*size);ring.rotation.x=Math.PI/2;ring.userData.life=.55;ring.userData.grow=4*size;}
function clampArena(o,margin=15){o.x=Math.max(-margin,Math.min(margin,o.x));o.z=Math.max(-12.4,Math.min(12.4,o.z))}
function movePlayer(dt){let p=state.player;if(!p)return;let pos=p.group.position,dx=(state.keys.d?1:0)-(state.keys.a?1:0),dz=(state.keys.s?1:0)-(state.keys.w?1:0);if(state.mode==='ball'){if(dx)p.yaw+=dx*dt*2.35;let throttle=(state.keys.w?1:0)-(state.keys.s?1:0);let forwardX=-Math.sin(p.yaw),forwardZ=-Math.cos(p.yaw);let boost=state.keys.space||state.keys.shift;let accel=boost&&state.boost>0?15:8;p.vx+=forwardX*throttle*accel*dt;p.vz+=forwardZ*throttle*accel*dt;if(boost&&throttle&&state.boost>0){state.boost=Math.max(0,state.boost-24*dt);if(Math.random()<.1)burst(pos.x,.3,pos.z,mats.orange,.3)}else state.boost=Math.min(100,state.boost+3*dt);let speed=Math.hypot(p.vx,p.vz),max=boost?13:8;if(speed>max){p.vx*=max/speed;p.vz*=max/speed}p.vx*=Math.pow(.985,dt*60);p.vz*=Math.pow(.985,dt*60);pos.x+=p.vx*dt;pos.z+=p.vz*dt;p.group.rotation.y=p.yaw;clampArena(pos,15);return}
if(state.mode==='skate'){let len=Math.hypot(dx,dz)||1;p.vx+=dx/len*22*dt;p.vz+=dz/len*22*dt;let speed=Math.hypot(p.vx,p.vz);if(speed>10){p.vx*=10/speed;p.vz*=10/speed}p.vx*=Math.pow(.94,dt*60);p.vz*=Math.pow(.94,dt*60);pos.x+=p.vx*dt;pos.z+=p.vz*dt;if(Math.abs(pos.x)>8.1&&Math.abs(pos.x)<10.3||Math.abs(pos.z)>7.1&&Math.abs(pos.z)<9.2){if(pos.y<.2){pos.y=1.1;state.score+=50;toast('RAMP HIT +50')}}if(pos.y>0)pos.y=Math.max(0,pos.y-dt*3);p.group.rotation.y=Math.atan2(p.vx,p.vz);p.group.rotation.y+=p.spin;p.spin*=.87;clampArena(pos,14);if(state.keys.space&&Math.random()<dt*2)doTrick('OLLIE');return}
let len=Math.hypot(dx,dz)||1;p.vx+=dx/len*13*dt;p.vz+=dz/len*13*dt;let speed=Math.hypot(p.vx,p.vz);if(speed>7){p.vx*=7/speed;p.vz*=7/speed}p.vx*=Math.pow(.87,dt*60);p.vz*=Math.pow(.87,dt*60);pos.x+=p.vx*dt;pos.z+=p.vz*dt;clampArena(pos,14);if(speed>.5)p.group.rotation.y=Math.atan2(p.vx,p.vz);
if(state.mode==='stand'){for(let n of state.arena.filter(a=>a.beam)){let d=Math.hypot(pos.x-n.x,pos.z-n.z);if(d<1.6&&n.charge<1){n.charge=Math.min(1,n.charge+dt*.32);n.beam.material=n.charge>.95?mats.cyan:mats.lime;if(n.charge>=1){n.done=true;state.nodes++;state.score+=500;burst(n.x,1,n.z,mats.lime,2);toast('RELAY '+state.nodes+' / 3 CHARGED +500');$('#objectiveValue').textContent=state.nodes+' / 3 NODES';$('#meter').style.width=(state.nodes/3*100)+'%';if(state.nodes===3){state.score+=1000;toast('ALL RELAYS ONLINE — FINISH THE WAVES');if(state.kills>=6)finish(true)}}}}
}
function moveEnemies(dt){if(!state.player)return;let p=state.player.group.position;for(let e of state.enemies){if(e.hp<=0){e.group.visible=false;continue}let q=e.group.position,dx=p.x-q.x,dz=p.z-q.z,d=Math.hypot(dx,dz)||.01;if(d>1.55){q.x+=dx/d*dt*(state.mode==='duel'?2.1:1.55);q.z+=dz/d*dt*(state.mode==='duel'?2.1:1.55);e.group.rotation.y=Math.atan2(-dx,-dz)}else{e.attack-=dt;if(e.attack<=0){e.attack=state.mode==='duel'?1.1:1.8;state.hp=Math.max(0,state.hp-(state.mode==='duel'?9:5));burst(p.x,.8,p.z,mats.orange,.55);if(state.hp<=0)finish(false)}}}}
if(state.mode==='duel'&&state.enemies[0]?.hp>0){let e=state.enemies[0];$('#objectiveValue').textContent=Math.max(0,Math.round(e.hp/50*100))+'% VITALS';$('#meter').style.width=Math.max(0,e.hp/50*100)+'%';if(e.hp<=0)finish(true)}
function updateBall(dt){if(!state.ball)return;let b=state.ball;b.vx*=Math.pow(.985,dt*60);b.vz*=Math.pow(.985,dt*60);b.x+=b.vx*dt;b.z+=b.vz*dt;if(Math.abs(b.x)>16){b.x=Math.sign(b.x)*16;b.vx*=-.75}if(Math.abs(b.z)>12.5){let team=b.z<0?'HOME':'AWAY';if(Math.abs(b.x)<3.1){if(team==='HOME'){state.ballScore++;state.score+=1000;toast('GOAL! +1000');burst(0,.8,b.z,mats.lime,3)}else{state.hp=Math.max(0,state.hp-10);toast('THEY SCORED — DEFEND YOUR NET')}$('#objectiveValue').textContent=state.ballScore+' GOALS';$('#meter').style.width=Math.min(100,state.ballScore*25)+'%';b.x=0;b.z=0;b.vx=0;b.vz=0}else{b.z=Math.sign(b.z)*12.4;b.vz*=-.65}}
let p=state.player,q=p.group.position,dx=b.x-q.x,dz=b.z-q.z,d=Math.hypot(dx,dz);if(d<1.45){let n=Math.max(d,.01);let v=Math.hypot(p.vx,p.vz);b.vx+=dx/n*(3+v*.85);b.vz+=dz/n*(3+v*.85);state.score+=1;burst(b.x,.5,b.z,mats.orange,.35)}b.mesh.position.set(b.x,.8+Math.sin(performance.now()*.003)*.12,b.z);b.mesh.rotation.x+=dt*1.6;b.mesh.rotation.z+=dt*1.3;
for(let c of state.crates){if(!c.active||c.carried)continue;if(Math.hypot(q.x-c.x,q.z-c.z)<1.6){c.carried=true;state.items++;state.score+=50;c.group.visible=false;toast('ITEM ACQUIRED — Q / E / R TO USE');$('#objectiveValue').textContent=state.items+' IN INVENTORY';$('#meter').style.width=Math.min(100,state.items*33)+'%'}}
// rival car chases and shoots the ball toward the player's goal
if(!state.rival){state.rival=makeCar(mats.red);state.rival.group.position.set(0,0,-9)}let r=state.rival,rp=r.group.position,tx=b.x-rp.x,tz=b.z-rp.z,angle=Math.atan2(-tx,-tz);let ad=((angle-r.yaw+Math.PI*3)%(Math.PI*2))-Math.PI;r.yaw+=Math.sign(ad)*Math.min(Math.abs(ad),dt*1.3);let f=Math.max(0,Math.cos(ad));r.vx+=-Math.sin(r.yaw)*f*4*dt;r.vz+=-Math.cos(r.yaw)*f*4*dt;rp.x+=r.vx*dt;rp.z+=r.vz*dt;r.vx*=.98;r.vz*=.98;r.group.rotation.y=r.yaw;let ex=b.x-rp.x,ez=b.z-rp.z,ed=Math.hypot(ex,ez);if(ed<1.5){b.vx+=ex/(ed||1)*2;b.vz+=ez/(ed||1)*2}clampArena(rp,14);
}
function finish(win){if(state.finished)return;state.finished=true;state.playing=false;$('#result').textContent=win?'VICTORY':'RUN OVER';$('#result').classList.add('show');$('#statusText').textContent=win?'MISSION COMPLETE':'SIGNAL LOST';toast(win?'CHALLENGE CLEARED':'RUN ENDED — RESET TO TRY AGAIN')}
let clock=0,last=performance.now();function tick(now){requestAnimationFrame(tick);let dt=Math.min(.04,(now-last)/1000);last=now;clock+=dt;if(state.playing){movePlayer(dt);moveEnemies(dt);updateBall(dt);if(state.mode==='skate'||state.mode==='ball'||state.mode==='duel'){state.time-=dt;if(state.mode==='skate'&&state.time<=0){state.time=0;finish(true);toast('SESSION COMPLETE — SCORE BANKED')}if(state.mode==='ball'&&state.time<=0){state.time=0;finish(state.ballScore>0)}if(state.mode==='duel'&&state.time<=0)finish(state.enemies[0]?.hp<state.player.hp)}}
if(state.mode==='skate'){let p=state.player;if(p&&p.group.position.y===0&&Math.hypot(p.vx,p.vz)<.5&&clock-state.lastTrick>3){state.combo=1;$('#combo').textContent='x1.0'}}
if(state.mode==='stand'&&state.nodes===3&&state.kills>=6)finish(true);
$('#timer').textContent=state.mode==='skate'||state.mode==='ball'?`${String(Math.floor(state.time/60)).padStart(2,'0')}:${String(Math.floor(state.time%60)).padStart(2,'0')}`:state.mode==='stand'?'WAVE '+String(state.wave).padStart(2,'0'):state.mode==='duel'?`${String(Math.floor(Math.max(0,state.time)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,state.time)%60)).padStart(2,'0')}`:'READY';
$('#score').innerHTML=String(state.score).padStart(3,'0')+'<span> PTS</span>';$('#health').textContent=state.mode==='ball'?Math.round(state.boost):state.hp;$('#combo').textContent=state.mode==='stand'?'W'+String(state.wave).padStart(2,'0'):'x'+state.combo.toFixed(1);
fx.children.forEach(o=>{if(o.userData.life){o.userData.life-=dt;o.scale.x+=dt*o.userData.grow;o.scale.y+=dt*o.userData.grow;if(o.userData.life<=0){fx.remove(o);o.geometry.dispose()}}});
// restrained camera follow with mode-specific composition
if(state.player){let p=state.player.group.position;let target=new THREE.Vector3(p.x*.22,0,p.z*.2);let desired=state.mode==='ball'?new THREE.Vector3(p.x*.6,22,p.z+27):state.mode==='skate'?new THREE.Vector3(p.x*.25+13,18,p.z*.25+19):new THREE.Vector3(p.x*.25+13,15,p.z*.25+19);camera.position.lerp(desired,dt*.7);camera.lookAt(target)}
renderer.render(scene,camera)}requestAnimationFrame(tick);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
// Intro scene gives a live preview before the first drop.
makeArena('stand');state.playing=false;state.player.group.position.set(-2,0,1);const ambientDecor=new THREE.Group();scene.add(ambientDecor);for(let i=0;i<26;i++){let x=(Math.random()-.5)*38,z=(Math.random()-.5)*30;if(Math.abs(x)<10&&Math.abs(z)<8)continue;let dot=mesh(ambientDecor,sphereGeo,i%3===0?mats.orange:mats.lime,x,.12+Math.random()*.12,z,.035,.035,.035);dot.userData.phase=Math.random()*6}
function idle(){for(let d of ambientDecor.children)d.position.y=.12+Math.sin(performance.now()*.002+d.userData.phase)*.08;renderer.render(scene,camera);if(!state.playing)requestAnimationFrame(idle)}idle();
</script></body></html>

